package httpserver

import "html/template"

var dashboardTemplates = template.Must(template.New("dashboard").Parse(`
{{define "setup"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Set up · DComic Sync</title><link rel="stylesheet" href="/dashboard/assets/styles.css"></head><body class="login-page"><main class="login-card setup-card"><p class="eyebrow">First-run setup</p><h1>Create root administrator</h1><p class="muted">Enter the initialization code shown in the server startup logs. The code is valid only for this server process.</p>{{if .Error}}<div class="alert">{{.Error}}</div>{{end}}<form method="post" action="/dashboard/setup"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>Username<input value="root" readonly aria-readonly="true"></label><label>Initialization code<input name="initializationCode" autocomplete="off" autocapitalize="none" spellcheck="false" required autofocus></label><label>Password<input type="password" name="password" minlength="12" maxlength="72" autocomplete="new-password" required><span class="field-help">Use 12–72 bytes.</span></label><label>Confirm password<input type="password" name="confirmPassword" minlength="12" maxlength="72" autocomplete="new-password" required></label><button type="submit">Create root account</button></form><p class="setup-footnote">After setup, this page is permanently disabled for this database.</p></main></body></html>{{end}}
{{define "login"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign in · DComic Sync</title><link rel="stylesheet" href="/dashboard/assets/styles.css"></head><body class="login-page"><main class="login-card"><h1>DComic Sync</h1><p class="muted">Administrator dashboard</p>{{if .Error}}<div class="alert">{{.Error}}</div>{{end}}<form method="post" action="/dashboard/login"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>Username<input name="username" autocomplete="username" required autofocus></label><label>Password<input type="password" name="password" autocomplete="current-password" required></label><button type="submit">Sign in</button></form></main></body></html>{{end}}
{{define "overview"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard · DComic Sync</title><link rel="stylesheet" href="/dashboard/assets/styles.css"></head><body><header><a class="brand" href="/dashboard">DComic Sync</a><div><span>{{.Admin.Username}}</span><form class="inline" method="post" action="/dashboard/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="link" type="submit">Sign out</button></form></div></header><main><div class="title"><div><h1>Overview</h1><p class="muted">Accounts and durable synchronization state</p></div></div>{{if .Notice}}<div class="notice">{{.Notice}}</div>{{end}}{{if .Error}}<div class="alert">{{.Error}}</div>{{end}}<section class="stats"><article><strong>{{.Stats.Users}}</strong><span>Users</span></article><article><strong>{{.Stats.Enabled}}</strong><span>Enabled</span></article><article><strong>{{.Stats.Devices}}</strong><span>Active devices</span></article><article><a href="#users"><strong>{{.Stats.Records}}</strong><span>Records</span></a></article><article><a href="#users"><strong>{{.Stats.Conflicts}}</strong><span>Conflicts</span></a></article></section><section class="panel"><h2>Create user</h2><form class="create-grid" method="post" action="/dashboard/users"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>Username<input name="username" minlength="3" maxlength="64" required></label><label>Initial password<input type="password" name="password" minlength="12" maxlength="72" autocomplete="new-password" required></label><button type="submit">Create</button></form></section><section class="panel" id="users"><h2>Users</h2><div class="table-wrap"><table><thead><tr><th>User</th><th>Status</th><th>Devices</th><th>Records</th><th>Conflicts</th><th>Cursor</th></tr></thead><tbody>{{range .Users}}<tr><td><a href="/dashboard/users/{{.ID}}"><strong>{{.Username}}</strong></a>{{if .Admin}} <span class="tag">admin</span>{{end}}</td><td>{{if .Disabled}}<span class="bad">Disabled</span>{{else}}<span class="good">Enabled</span>{{end}}</td><td>{{.DeviceCount}}</td><td><a href="/dashboard/users/{{.ID}}/sync">{{.RecordCount}}</a></td><td><a href="/dashboard/users/{{.ID}}#conflicts">{{.ConflictCount}}</a></td><td>{{.LatestCursor}}</td></tr>{{else}}<tr><td colspan="6">No users.</td></tr>{{end}}</tbody></table></div></section></main></body></html>{{end}}
{{define "user"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{.User.Username}} · DComic Sync</title><link rel="stylesheet" href="/dashboard/assets/styles.css"></head><body><header><a class="brand" href="/dashboard">DComic Sync</a><span>{{.Admin.Username}}</span></header><main><p><a href="/dashboard">← Overview</a></p><div class="title"><div><h1>{{.User.Username}}</h1><p class="muted">Created {{.User.CreatedAt.Format "2006-01-02 15:04 UTC"}}</p></div>{{if .User.Disabled}}<form method="post" action="/dashboard/users/{{.User.ID}}/enable"><input type="hidden" name="csrf" value="{{.CSRF}}"><button type="submit">Enable account</button></form>{{else}}<form method="post" action="/dashboard/users/{{.User.ID}}/disable"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="danger" type="submit">Disable account</button></form>{{end}}</div>{{if .Notice}}<div class="notice">{{.Notice}}</div>{{end}}{{if .Error}}<div class="alert">{{.Error}}</div>{{end}}<section class="stats"><article><strong>{{.User.DeviceCount}}</strong><span>Active devices</span></article><article><a href="/dashboard/users/{{.User.ID}}/sync"><strong>{{.User.RecordCount}}</strong><span>Records</span></a></article><article><a href="#conflicts"><strong>{{.User.ConflictCount}}</strong><span>Conflicts</span></a></article><article><a href="/dashboard/users/{{.User.ID}}/sync"><strong>{{.User.LatestCursor}}</strong><span>Latest cursor</span></a></article></section><section class="panel"><h2>Reset password</h2><p class="muted">This immediately revokes every API and dashboard session for this user.</p><form class="create-grid" method="post" action="/dashboard/users/{{.User.ID}}/password"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>New password<input type="password" name="password" minlength="12" maxlength="72" autocomplete="new-password" required></label><button class="danger" type="submit">Reset and revoke</button></form></section><section class="panel"><h2>Devices</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Device ID</th><th>Last seen</th><th>Expires</th><th>Status</th><th></th></tr></thead><tbody>{{range .Devices}}<tr><td>{{.Name}}</td><td><code>{{.DeviceID}}</code></td><td>{{.LastSeen.Format "2006-01-02 15:04"}}</td><td>{{.ExpiresAt.Format "2006-01-02"}}</td><td>{{if .Revoked}}Revoked{{else}}Active{{end}}</td><td>{{if not .Revoked}}<form method="post" action="/dashboard/users/{{$.User.ID}}/devices/{{.ID}}/revoke"><input type="hidden" name="csrf" value="{{$.CSRF}}"><button class="small danger" type="submit">Revoke</button></form>{{end}}</td></tr>{{else}}<tr><td colspan="6">No devices.</td></tr>{{end}}</tbody></table></div></section>
<section class="panel" id="conflicts"><div class="section-title"><div><h2>Conflicts</h2><p class="muted">Choose which side becomes the synchronized value.</p></div><a href="/dashboard/users/{{.User.ID}}/sync">Open sync details</a></div>
{{range .Conflicts}}<article class="conflict"><h3><code>{{.Candidate.Category}} / {{.Candidate.Key}}</code></h3><div class="conflict-grid">
<section><h4>Candidate</h4><p class="metadata">{{.Candidate.DeviceName}} · <code>{{.Candidate.DeviceID}}</code><br>HLC version {{.Candidate.Version.Wall}}:{{.Candidate.Version.Logical}}</p><details><summary>{{if .Candidate.Deleted}}Deleted tombstone{{else if .Candidate.Redacted}}Redacted payload{{else}}View payload{{end}}</summary><pre>{{.Candidate.Value}}</pre></details><form method="post" action="/dashboard/users/{{$.User.ID}}/conflicts/{{.ID}}/resolve"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="choice" value="candidate"><input type="hidden" name="expectedWall" value="{{.ExpectedWall}}"><input type="hidden" name="expectedLogical" value="{{.ExpectedLogical}}"><input type="hidden" name="expectedDevice" value="{{.ExpectedDevice}}"><button type="submit">Use candidate</button></form></section>
<section><h4>Current server value</h4><p class="metadata">{{.Current.DeviceName}} · <code>{{.Current.DeviceID}}</code><br>HLC version {{.Current.Version.Wall}}:{{.Current.Version.Logical}}</p><details><summary>{{if .Current.Deleted}}Deleted tombstone{{else if .Current.Redacted}}Redacted payload{{else}}View payload{{end}}</summary><pre>{{.Current.Value}}</pre></details><form method="post" action="/dashboard/users/{{$.User.ID}}/conflicts/{{.ID}}/resolve"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="choice" value="server"><input type="hidden" name="expectedWall" value="{{.ExpectedWall}}"><input type="hidden" name="expectedLogical" value="{{.ExpectedLogical}}"><input type="hidden" name="expectedDevice" value="{{.ExpectedDevice}}"><button type="submit">Keep current</button></form></section>
</div></article>{{else}}<p>No unresolved conflicts.</p>{{end}}</section>
<section class="panel"><h2>Sync state</h2><p>Durable records: <a href="/dashboard/users/{{.User.ID}}/sync"><strong>{{.User.RecordCount}}</strong></a> · unresolved conflicts: <a href="#conflicts"><strong>{{.User.ConflictCount}}</strong></a> · latest cursor: <strong>{{.User.LatestCursor}}</strong></p><p class="muted">Credential payloads are never shown in the dashboard.</p></section></main></body></html>{{end}}
{{define "sync-details"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sync details · {{.User.Username}} · DComic Sync</title><link rel="stylesheet" href="/dashboard/assets/styles.css"></head><body><header><a class="brand" href="/dashboard">DComic Sync</a><span>{{.Admin.Username}}</span></header><main><p><a href="/dashboard/users/{{.User.ID}}">← {{.User.Username}}</a></p><div class="title"><div><h1>Sync details</h1><p class="muted">Accepted changes in newest-first order. Receipt time and HLC version are shown separately.</p></div></div>
<nav class="category-filter" aria-label="Sync category"><a class="{{if not .Category}}active{{end}}" href="/dashboard/users/{{.User.ID}}/sync">All</a>{{range .Categories}}<a class="{{if eq $.Category .Category}}active{{end}}" href="/dashboard/users/{{$.User.ID}}/sync?category={{.Category}}">{{.Category}} <span>{{.Records}} records · {{.Deleted}} deleted · {{.Conflicts}} conflicts</span></a>{{end}}</nav>
<section class="panel"><h2>{{if .Category}}{{.Category}}{{else}}All categories{{end}} changes</h2><p class="muted">{{.Stats.Records}} current records · {{.Stats.Deleted}} deleted · {{.Stats.Conflicts}} unresolved conflicts</p>{{range .Changes}}<article class="change"><h3><code>{{.Category}} / {{.Key}}</code></h3><p class="metadata">Accepted change #{{.Sequence}} · Source: {{.DeviceName}} · <code>{{.DeviceID}}</code><br>Server receipt: {{.ReceivedAt.Format "2006-01-02 15:04:05 UTC"}} · HLC version: {{.Version.Wall}}:{{.Version.Logical}}</p><details><summary>{{if .Deleted}}Deleted tombstone{{else if .Redacted}}Redacted payload{{else}}View synchronized payload{{end}}</summary><pre>{{.Value}}</pre></details></article>{{else}}<p>No accepted changes in this selection.</p>{{end}}{{if .NextURL}}<p class="pagination"><a href="{{.NextURL}}">Older changes →</a></p>{{end}}</section>
{{if .Conflicts}}<section class="panel" id="conflicts"><h2>Unresolved conflicts</h2><p>Resolve conflicts on the <a href="/dashboard/users/{{.User.ID}}#conflicts">{{.User.Username}} account page</a>.</p>{{range .Conflicts}}<p><code>{{.Candidate.Category}} / {{.Candidate.Key}}</code> — {{.Candidate.DeviceName}} versus {{.Current.DeviceName}}</p>{{end}}</section>{{end}}</main></body></html>{{end}}
`))

const dashboardCSS = `:root{color-scheme:light;font-family:Inter,ui-sans-serif,system-ui,-apple-system,sans-serif;background:#f5f7fb;color:#172033}*{box-sizing:border-box}body{margin:0}a{color:#275bd8;text-decoration:none}a:hover{text-decoration:underline}header{height:64px;padding:0 max(20px,calc((100vw - 1160px)/2));display:flex;align-items:center;justify-content:space-between;background:#111a2e;color:#fff;gap:20px}.brand{font-size:1.15rem;font-weight:750;color:#fff}main{max-width:1160px;margin:0 auto;padding:28px 20px 60px}.title{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:24px}h1{margin:0 0 4px;font-size:clamp(1.7rem,4vw,2.3rem)}h2{margin:0 0 18px;font-size:1.15rem}.muted{color:#69758b;margin:.35rem 0 1rem}.stats{display:grid;grid-template-columns:repeat(5,minmax(120px,1fr));gap:14px;margin-bottom:22px}.stats article,.panel,.login-card{background:#fff;border:1px solid #e1e6ef;border-radius:12px;box-shadow:0 3px 14px rgba(17,26,46,.05)}.stats article{padding:18px}.stats strong{display:block;font-size:1.75rem}.stats span{color:#69758b;font-size:.87rem}.panel{padding:22px;margin-bottom:22px}.create-grid{display:grid;grid-template-columns:1fr 1.5fr auto;gap:14px;align-items:end}label{display:grid;gap:7px;font-size:.87rem;font-weight:650}input{width:100%;padding:10px 12px;border:1px solid #bac3d2;border-radius:8px;font:inherit;background:#fff}input:focus{outline:3px solid #d8e3ff;border-color:#275bd8}button{border:0;border-radius:8px;background:#275bd8;color:#fff;font:inherit;font-weight:700;padding:10px 16px;cursor:pointer}button:hover{filter:brightness(.93)}button.danger{background:#b52832}.small{padding:7px 10px;font-size:.82rem}.inline{display:inline}.link{background:transparent;padding:6px 8px;color:#bcd0ff}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:680px}th,td{text-align:left;padding:12px;border-bottom:1px solid #e7eaf0;font-size:.9rem}th{color:#69758b;font-size:.78rem;text-transform:uppercase;letter-spacing:.04em}.tag{background:#e5ecff;color:#214da8;border-radius:99px;padding:3px 7px;font-size:.7rem}.good{color:#167044}.bad{color:#aa2630}.notice,.alert{padding:12px 14px;border-radius:8px;margin:0 0 18px}.notice{background:#e5f5ec;color:#12623b}.alert{background:#fde8ea;color:#8d2029}.login-page{min-height:100vh;display:grid;place-items:center;padding:20px;background:linear-gradient(145deg,#101a31,#274b91)}.login-card{width:min(420px,100%);padding:32px}.login-card form{display:grid;gap:18px}.login-card button{margin-top:4px}code{font-size:.82rem}@media(max-width:800px){.stats{grid-template-columns:repeat(2,1fr)}.create-grid{grid-template-columns:1fr}.title{align-items:flex-start;flex-direction:column}header{height:auto;padding-top:14px;padding-bottom:14px}}@media(max-width:420px){main{padding-left:14px;padding-right:14px}.stats{grid-template-columns:1fr 1fr}.panel{padding:16px}}`

const dashboardSyncCSS = `.section-title{display:flex;align-items:flex-start;justify-content:space-between;gap:18px}.conflict{border-top:1px solid #e7eaf0;padding:18px 0}.conflict:first-of-type{border-top:0;padding-top:0}.conflict-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.conflict-grid>section{border:1px solid #e1e6ef;border-radius:9px;padding:16px}.conflict-grid form{margin-top:14px}.metadata{color:#69758b;font-size:.86rem;line-height:1.55}.category-filter{display:flex;flex-wrap:wrap;gap:9px;margin-bottom:22px}.category-filter a{display:grid;background:#fff;border:1px solid #d5dbe6;border-radius:9px;padding:9px 12px}.category-filter a.active{border-color:#275bd8;background:#edf2ff}.category-filter span{color:#69758b;font-size:.75rem}.change{border-top:1px solid #e7eaf0;padding:16px 0}.change:first-of-type{border-top:0;padding-top:0}details{margin:.65rem 0}summary{color:#275bd8;cursor:pointer;font-weight:650}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f7fb;border-radius:8px;padding:13px;font-size:.82rem}.pagination{text-align:right;margin-bottom:0}@media(max-width:700px){.conflict-grid{grid-template-columns:1fr}.section-title{display:block}}`
